from fractions import Fraction

def gcd(a, b):
    return math.gcd(a, b)

def get_tan_multiple(n, t):
    """Computes tan(n*arctan(t)) given t=tan(theta). t must be a Fraction."""
    if n == 0:
        return Fraction(0)
    if n == 1:
        return t
    # Using tan(A+B) formula, tan(n*theta) = tan((n-1)theta + theta)
    # This is less efficient but conceptually simple.
    # A better way is to use a cache/memoization.
    tan_prev = t
    for _ in range(n - 1):
        tan_curr = (tan_prev + t) / (1 - tan_prev * t)
        tan_prev = tan_curr
    return tan_prev

def generator(rng):
