        a, b = b, a

    # To ensure the problem is well-posed and intermediate tangents are < 1,
    # we need tan(x0/2) < tan(pi / (4*max(a,b))).
    # tan(pi/8) ~ 0.414, tan(pi/12) ~ 0.268, tan(pi/16) ~ 0.199
