    if not (abs(t_a) < 1 and abs(t_b) < 1):
        # This should not happen with the chosen q_min values.
        # Retry if it does.
        return generator(rng)

    # V = sec(ax) + tan(ax) = (1 + tan(ax/2)) / (1 - tan(ax/2))
    V = (1 + t_a) / (1 - t_a)

    # W = sec(bx) + tan(bx) = (1 + tan(bx/2)) / (1 - tan(bx/2))
